async function extract(bytes, pages, includeImages, signal) {
  if (signal?.aborted) throw stopError(signal);
  const worker = new Worker(new URL('./pdf-worker.mjs', import.meta.url), {
    workerData: { bytes: Uint8Array.from(bytes), pages, includeImages },
    execArgv: [], stdout: true, stderr: true,
    resourceLimits: { maxOldGenerationSizeMb: 128, maxYoungGenerationSizeMb: 32 },
  });
  worker.stdout.resume();
  worker.stderr.resume();
  try {
    return await new Promise((resolve, reject) => {
      const onTimeout = () => reject(new Error('Reading the PDF timed out.'));
      const abort = () => reject(stopError(signal));
      const timer = setTimeout(onTimeout, WORKER_TIMEOUT_MS);
      const clean = () => { clearTimeout(timer); signal?.removeEventListener('abort', abort); };
      worker.once('message', message => { clean(); if (message.error) reject(new Error(message.error)); else resolve(message); });
      worker.once('error', error => { clean(); reject(error); });
      worker.once('exit', code => { clean(); reject(new Error(`PDF worker exited before returning a result (${code}).`)); });
      signal?.addEventListener('abort', abort, { once: true });
      if (signal?.aborted) abort();
    });
  } finally {
    await worker.terminate();
  }
}
```

