// Throwaway end-to-end smoke: the real src/pdf.mjs driving the real pdfium worker over generated PDFs.
import { mkdtemp, mkdir, writeFile, readFile, stat, rm } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import { join, dirname } from 'node:path';
import { pathToFileURL } from 'node:url';

const failures = [];
let checks = 0;
const check = (condition, label) => { checks++; if (!condition) failures.push(label); console.log(`${condition ? 'ok  ' : 'FAIL'} ${label}`); };

function buildPdf(pageTexts) {
  const chunks = [];
  const offsets = [];
  let offset = 0;
  const push = text => { const buf = Buffer.from(text, 'latin1'); chunks.push(buf); offset += buf.length; };
  const add = (number, body) => { offsets[number] = offset; push(`${number} 0 obj\n${body}\nendobj\n`); };
  push('%PDF-1.7\n');
  const kids = pageTexts.map((_, index) => `${4 + index * 2} 0 R`).join(' ');
  add(1, '<< /Type /Catalog /Pages 2 0 R >>');
  add(2, `<< /Type /Pages /Kids [${kids}] /Count ${pageTexts.length} >>`);
  add(3, '<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica >>');
  pageTexts.forEach((text, index) => {
    const page = 4 + index * 2;
    add(page, `<< /Type /Page /Parent 2 0 R /MediaBox [0 0 612 792] /Resources << /Font << /F1 3 0 R >> >> /Contents ${page + 1} 0 R >>`);
    const stream = `BT /F1 24 Tf 72 700 Td (${text}) Tj ET`;
    add(page + 1, `<< /Length ${stream.length} >>\nstream\n${stream}\nendstream`);
  });
  const startxref = offset;
  push(`xref\n0 ${offsets.length}\n0000000000 65535 f \n`);
  for (let number = 1; number < offsets.length; number++) push(`${String(offsets[number]).padStart(10, '0')} 00000 n \n`);
  push(`trailer\n<< /Size ${offsets.length} /Root 1 0 R >>\nstartxref\n${startxref}\n%%EOF\n`);
  return Buffer.concat(chunks);
}

const root = await mkdtemp(join(tmpdir(), 'pdf-real-'));
const vaultRoot = join(root, 'vault');
const safe = rel => {
  const abs = join(vaultRoot, rel);
  if (!abs.startsWith(vaultRoot)) throw new Error(`path escape: ${rel}`);
  return abs;
};
const vault = {
  readFile: rel => readFile(safe(rel), 'utf8'),
  writeFile: async (rel, data) => { await mkdir(dirname(safe(rel)), { recursive: true }); await writeFile(safe(rel), data); return rel; },
  exists: async rel => { try { await stat(safe(rel)); return true; } catch { return false; } },
};

const single = join(root, 'single.pdf');
await writeFile(single, buildPdf(['Hello PDF from page one']));
const three = join(root, 'three.pdf');
await writeFile(three, buildPdf(['Alpha page', 'Bravo page', 'Charlie page']));

const { readPdfPages } = await import(pathToFileURL('C:/Users/basam/pi-discover/src/pdf.mjs').href);

const one = await readPdfPages({ file: single, vault });
check(one.totalPages === 1 && one.pages.length === 1 && one.pages[0].text.includes('Hello PDF from page one'), `single page text: ${JSON.stringify(one.pages[0]?.text)}`);
check(one.pages[0].truncated === false && one.images.length === 0 && one.truncatedPages === 0, 'single page record defaults');

const threeFirst = await readPdfPages({ file: three, vault });
check(threeFirst.totalPages === 3 && JSON.stringify(threeFirst.pages.map(page => page.number)) === '[1,2,3]', 'three pages discovered through the probe');
check(threeFirst.pages[1].text.includes('Bravo page') && threeFirst.pages[2].text.includes('Charlie page'), 'all three page texts extracted');
const cached = await readPdfPages({ file: three, vault });
check(JSON.stringify(cached.pages) === JSON.stringify(threeFirst.pages), 'cached reread identical');
const onlyTwo = await readPdfPages({ file: three, vault, pages: [2] });
check(onlyTwo.pages.length === 1 && onlyTwo.pages[0].text.includes('Bravo page') && onlyTwo.totalPages === 3, 'single cached page read');

const withImages = await readPdfPages({ file: three, vault, includeImages: true, pages: [2, 3] });
const png = Buffer.from(withImages.images[0]?.data ?? '', 'base64');
check(withImages.images.length === 2 && withImages.images.every(image => image.mimeType === 'image/png'), 'image request returns two renders');
check(png.subarray(0, 8).equals(Buffer.from([0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a])) && png.length > 100, `render is a real PNG (${png.length} bytes)`);
const written = await readFile(safe(withImages.pages[0].imagePath));
check(written.equals(png) && withImages.pages[0].imagePath.endsWith(`/${withImages.sha48}/page-0002.png`), 'render written to _discover/pdf/<sha48>');
check((await stat(safe(withImages.pages[0].imagePath))).size === png.length, 'PNG on disk matches the returned bytes');

await rm(root, { recursive: true, force: true });
console.log(`\n${checks - failures.length}/${checks} checks passed`);
if (failures.length) { console.log(failures.map(failure => `- ${failure}`).join('\n')); process.exitCode = 1; }

