// Staged documents for the next message. Pasted images never come through here:
// Pi hands those to the input event directly. A staged PDF is extracted once per
// turn, cached by content hash, and stored as a citable source note.
import { stat } from 'node:fs/promises';
import { basename, extname, resolve } from 'node:path';
import { readPdfPages } from './pdf.mjs';

const MAX_BYTES = 50 * 1024 * 1024;
const MAX_STAGED = 5;
const MAX_TEXT = 12_000;
const MAX_IMAGES = 2;
const PAGE_HINT = /\b(?:pages?|pp?)\.?\s*(\d{1,4})\b|§\s*(\d{1,4})/gi;

/** Page numbers the question asks about, in order, at most two. */
function pageHints(question) {
  const numbers = [];
  for (const match of String(question ?? '').matchAll(PAGE_HINT)) {
    const number = Number(match[1] || match[2]);
    if (Number.isInteger(number) && number >= 1 && number <= 2000 && !numbers.includes(number)) numbers.push(number);
    if (numbers.length === 2) break;
  }
  return numbers;
}

const acceptsImages = model => Array.isArray(model?.input) && model.input.includes('image');

export function createAttachments({ vault }) {
  const staged = [];

  async function stage(input) {
    const value = String(input ?? '').trim();
    if (!value) throw new Error('Provide a file path to stage.');
    const file = resolve(value);
    const info = await stat(file).catch(error => {
      if (error.code === 'ENOENT') throw new Error(`${value}: file not found.`);
      throw error;
    });
    if (!info.isFile()) throw new Error(`${value}: file not found.`);
    if (extname(file).toLowerCase() !== '.pdf') throw new Error('Only PDF files can be staged; paste images with Alt+V.');
    if (info.size > MAX_BYTES) throw new Error(`${value}: larger than 50 MiB.`);
    if (staged.length >= MAX_STAGED) throw new Error(`At most ${MAX_STAGED} files can be staged; clear them first.`);
    if (!staged.some(entry => entry.file === file)) {
      staged.push({ file, name: basename(file, extname(file)) || 'Document', bytes: info.size });
    }
    return staged.map(entry => entry.name);
  }

  function clear() {
    staged.length = 0;
  }

  /**
   * The writer's document evidence: page text, page renders when the question
   * asks for pages and the model can read them, and one citable source per file.
   */
  async function evidence({ question = '', model, signal } = {}) {
    if (!staged.length) return { text: '', images: [], sources: [] };
    const hints = pageHints(question);
    const textParts = [];
    const images = [];
    const sources = [];
    for (const entry of staged) {
      const wantsImages = acceptsImages(model) && hints.length > 0;
      const result = await readPdfPages({
        file: entry.file, vault, signal,
        pages: hints.length ? hints : undefined,
        includeImages: wantsImages || acceptsImages(model),
      });
      const pages = hints.length ? result.pages : result.pages.filter(page => page.number <= 20);
      const text = pages.map(page => `## Page ${page.number}\n\n${page.text}`).join('\n\n');
      const stored = await vault.storeSource({
        url: entry.file, title: entry.name, kind: 'pdf', hash: result.sha256, text,
      });
      sources.push({ id: stored.id, ref: stored.ref, title: stored.title, path: stored.path, url: entry.file });
      const heading = `# ${entry.name}\n(${result.totalPages} pages${result.truncatedPages ? `, first ${result.totalPages - result.truncatedPages} read` : ''})`;
      textParts.push(`${heading}\n\n${text}`);
      for (const image of result.images || []) {
        if (images.length >= MAX_IMAGES) break;
        images.push({ type: 'image', data: image.data, mimeType: image.mimeType || 'image/png', page: image.number, file: entry.name });
      }
    }
    const text = textParts.join('\n\n').trim();
    return {
      text: text.length > MAX_TEXT ? `${text.slice(0, MAX_TEXT)}\n…(attachment text truncated)` : text,
      images,
      sources,
    };
  }

  return { stage, clear, list: () => staged.map(entry => entry.name), evidence };
}

