// Throwaway smoke harness for src/pdf.mjs. Runs the module against a stub worker + stub vault.
import { mkdtemp, mkdir, writeFile, readFile, readdir, rm, stat, truncate } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import { join, dirname } from 'node:path';
import { pathToFileURL } from 'node:url';

const failures = [];
let checks = 0;
const check = (condition, label) => { checks++; if (!condition) failures.push(label); console.log(`${condition ? 'ok  ' : 'FAIL'} ${label}`); };
const expects = (actual, expected, label) => check(JSON.stringify(actual) === JSON.stringify(expected), `${label} -> ${JSON.stringify(actual)}`);
const rejects = async (promise, message, label) => {
  try { await promise; check(false, `${label} (resolved instead of rejecting)`); }
  catch (error) { check(error instanceof Error && error.message === message, `${label} -> ${error.message}`); }
};

const root = await mkdtemp(join(tmpdir(), 'pdf-smoke-'));
const source = await readFile('C:/Users/basam/pi-discover/src/pdf.mjs', 'utf8');
const patched = source.replaceAll("'./pdf-worker.mjs'", "'./stub-worker.mjs'");
check(patched !== source && !patched.includes("'./pdf-worker.mjs'"), 'worker url swapped in the copied module');
const modulePath = join(root, 'pdf-under-test.mjs');
await writeFile(modulePath, patched);
await writeFile(join(root, 'stub-worker.mjs'), `
import { parentPort, workerData } from 'node:worker_threads';
import { appendFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { dirname, join } from 'node:path';
appendFileSync(join(dirname(fileURLToPath(import.meta.url)), 'spawns.log'), JSON.stringify({ pages: workerData.pages, includeImages: workerData.includeImages }) + '\\n');
if (process.env.SMOKE_HANG) { setInterval(() => {}, 1000); } else if (process.env.SMOKE_FAIL) {
  parentPort.postMessage({ error: process.env.SMOKE_FAIL });
} else {
  const totalPages = Number(process.env.SMOKE_TOTAL || 3);
  if (workerData.pages.some(page => page > totalPages)) parentPort.postMessage({ error: 'PDF has ' + totalPages + ' pages; requested page is out of range.' });
  else {
    const pages = workerData.pages.map(number => {
      const text = process.env.SMOKE_LONG ? 'y'.repeat(24000) : 'page ' + number + ' of ' + totalPages + '\\n';
      const record = { number, text, truncated: false };
      if (workerData.includeImages) record.image = { data: new Uint8Array(process.env.SMOKE_BIG ? 9 * 1024 * 1024 : 8), width: 4, height: 4, marker: number };
      return record;
    });
    parentPort.postMessage({ totalPages, pages });
  }
}
`);

const vaultRoot = join(root, 'vault');
const safe = rel => {
  const abs = join(vaultRoot, rel);
  if (!abs.startsWith(vaultRoot)) throw new Error(`path escape: ${rel}`);
  return abs;
};
const vault = {
  readFile: rel => readFile(safe(rel), 'utf8'),
  // Mirrors the atomic fs.writeFile the real vault uses: strings and Buffers both pass through.
  writeFile: async (rel, data) => { await mkdir(dirname(safe(rel)), { recursive: true }); await writeFile(safe(rel), data); return rel; },
  exists: async rel => { try { await stat(safe(rel)); return true; } catch { return false; } },
};

const pdfBytes = fill => Buffer.concat([Buffer.from('%PDF-1.7\n'), Buffer.alloc(503, fill)]);
const makePdf = async (name, fill) => { const path = join(root, name); await writeFile(path, pdfBytes(fill)); return path; };
const spawnLog = join(root, 'spawns.log');
const spawns = async () => { try { return (await readFile(spawnLog, 'utf8')).trim().split('\n').filter(Boolean).map(JSON.parse); } catch { return []; } };
const runCount = async () => (await spawns()).length;
const signature = list => list.map(entry => `${entry.includeImages ? 'img' : 'txt'}:${entry.pages.join(',')}`);

const { readPdfPages } = await import(pathToFileURL(modulePath).href);

// 1. missing file, directory, non-PDF, oversized
await rejects(readPdfPages({ file: join(root, 'missing.pdf'), vault }), `${join(root, 'missing.pdf')}: file not found.`, 'missing file');
await rejects(readPdfPages({ file: root, vault }), `${root}: file not found.`, 'directory as file');
const junk = join(root, 'junk.bin'); await writeFile(junk, Buffer.alloc(64, 7));
await rejects(readPdfPages({ file: junk, vault }), 'That file is not a PDF.', 'no PDF marker');
const big = join(root, 'big.pdf'); await writeFile(big, Buffer.from('%PDF-1.7')); await truncate(big, 50 * 1024 * 1024 + 1);
await rejects(readPdfPages({ file: big, vault }), 'The PDF is larger than 50 MiB.', 'over 50 MiB');

// 2. fresh 25-page PDF, default pages: probe then the rest, capped at 20
process.env.SMOKE_TOTAL = '25';
const long = await makePdf('long.pdf', 1);
const first = await readPdfPages({ file: long, vault });
check(first.totalPages === 25 && first.truncatedPages === 5 && first.sha48.length === 48 && first.sha256.length === 64, 'fresh default: totals and hashes');
expects(first.pages.map(page => page.number), Array.from({ length: 20 }, (_, i) => i + 1), 'fresh default: pages 1..20');
check(first.pages[0].text === 'page 1 of 25\n' && first.pages[0].truncated === false && first.images.length === 0, 'fresh default: page record shape');
expects(signature(await spawns()), ['txt:1', `txt:${Array.from({ length: 19 }, (_, i) => i + 2).join(',')}`], 'fresh default: probe then remaining pages');
const meta = JSON.parse(await readFile(safe(`_discover/pdf/${first.sha48}/meta.json`), 'utf8'));
check(meta.version === 'pdfium-2.1.13-v1' && meta.sha256 === first.sha256 && meta.totalPages === 25 && typeof meta.extractedAt === 'string', 'meta.json content');
check(await vault.exists(`_discover/pdf/${first.sha48}/page-0020.txt`) && !(await vault.exists(`_discover/pdf/${first.sha48}/page-0021.txt`)), 'text files only for extracted pages');

// 3. cache hits: no worker spawn even when the worker is broken
process.env.SMOKE_FAIL = 'worker must not run';
const before = await runCount();
const second = await readPdfPages({ file: long, vault });
check(JSON.stringify(second.pages) === JSON.stringify(first.pages) && second.truncatedPages === 5, 'cache hit: identical output');
check((await runCount()) === before, 'cache hit: no worker spawn');
const seven = await readPdfPages({ file: long, vault, pages: [7] });
check(seven.pages.length === 1 && seven.pages[0].number === 7 && seven.totalPages === 25, 'cache hit: single requested page');
check((await runCount()) === before, 'cache hit: single page without worker');
const outOfRange = await readPdfPages({ file: long, vault, pages: [30] });
check(outOfRange.pages.length === 0 && outOfRange.truncatedPages === 0 && (await runCount()) === before, 'request beyond totalPages: empty, no worker');
const deduped = await readPdfPages({ file: long, vault, pages: [9, 9, 0, -2, '8', 4] });
expects(deduped.pages.map(page => page.number), [4, 9], 'pages deduped, sorted, invalid dropped');
check(deduped.truncatedPages === 0, 'explicit page list never reports truncated pages');
delete process.env.SMOKE_FAIL;

// 4. short PDF: probe learns the count, defaults clipped
process.env.SMOKE_TOTAL = '3';
const short = await makePdf('short.pdf', 2);
const shortFirst = await readPdfPages({ file: short, vault });
check(shortFirst.totalPages === 3 && shortFirst.truncatedPages === 0, 'short PDF: default request clipped to 3 pages');
expects(shortFirst.pages.map(page => page.number), [1, 2, 3], 'short PDF: pages 1..3');
expects(signature((await spawns()).slice(-2)), ['txt:1', 'txt:2,3'], 'short PDF: probe then remaining pages');
const shortCached = await readPdfPages({ file: short, vault });
check(JSON.stringify(shortCached.pages) === JSON.stringify(shortFirst.pages), 'short PDF: cached reread');

// 5. images: only the kept pages are rendered, PNG bytes written, base64 returned
process.env.SMOKE_TOTAL = '4';
const imaged = await makePdf('imaged.pdf', 3);
const imageSpawns = (await spawns()).length;
const withImages = await readPdfPages({ file: imaged, vault, includeImages: true });
expects(withImages.pages.map(page => page.number), [1, 2, 3, 4], 'images: every requested page present');
check(withImages.pages[0].imagePath.endsWith('page-0001.png') && withImages.pages[1].imagePath.endsWith('page-0002.png') && withImages.pages[2].imagePath === undefined, 'images: first two pages carry imagePath');
check(withImages.images.length === 2 && withImages.images[0].mimeType === 'image/png' && Buffer.from(withImages.images[0].data, 'base64').length === 8, 'images: two returned as base64 PNG');
check((await stat(safe(withImages.pages[0].imagePath))).size === 8 && !(await vault.exists(`_discover/pdf/${withImages.sha48}/page-0003.png`)), 'images: PNG written, extra page dropped silently');
expects(signature((await spawns()).slice(imageSpawns)), ['img:1', 'img:2', 'txt:3,4'], 'images: only render pages are rendered in the image calls');
check((await spawns()).every(entry => !entry.includeImages || entry.pages.length <= 2), 'images: no worker call renders more than two pages');
const imageRuns = (await spawns()).length;
const imagesAgain = await readPdfPages({ file: imaged, vault, includeImages: true });
check(imagesAgain.images.length === 2 && imagesAgain.pages[0].imagePath === withImages.pages[0].imagePath && (await spawns()).length === imageRuns + 1, 'images: cached text still yields a render without re-extracting the text');
const textOnly = await readPdfPages({ file: imaged, vault });
check(textOnly.images.length === 0 && textOnly.pages.length === 4 && (await spawns()).length === imageRuns + 1, 'text-only read of an imaged PDF stays cached');
process.env.SMOKE_BIG = '1';
const bigImage = await readPdfPages({ file: imaged, vault, includeImages: true });
check(bigImage.images.length === 0 && bigImage.pages.length === 4 && bigImage.pages[0].imagePath === undefined, 'images: over 8 MiB dropped silently');
delete process.env.SMOKE_BIG;

// 6. cached page at the character cap is reported as truncated
process.env.SMOKE_LONG = '1';
const longText = await makePdf('longtext.pdf', 4);
const longFirst = await readPdfPages({ file: longText, vault, pages: [1] });
check(longFirst.pages[0].truncated === false && longFirst.pages[0].text.length === 24000, 'page at the cap: worker flag trusted on first read');
const longCached = await readPdfPages({ file: longText, vault, pages: [1] });
check(longCached.pages[0].truncated === true, 'page at the cap: cached read reports truncated');
delete process.env.SMOKE_LONG;

// 7. worker failures and cancellation
const failing = await makePdf('failing.pdf', 5);
process.env.SMOKE_FAIL = 'Could not read PDF: broken document';
await rejects(readPdfPages({ file: failing, vault }), 'Could not read PDF: broken document', 'worker error string propagates');
delete process.env.SMOKE_FAIL;
const cancelled = new AbortController();
cancelled.abort(new Error('turn stopped'));
await rejects(readPdfPages({ file: failing, vault, signal: cancelled.signal }), 'turn stopped', 'aborted before the worker call');
const bare = new AbortController();
bare.abort();
const bareReason = bare.signal.reason;
try {
  await readPdfPages({ file: failing, vault, signal: bare.signal });
  check(false, 'aborted without a reason (resolved)');
} catch (error) {
  // Mirrors the documented rule: the signal reason when it is an Error, otherwise a plain message.
  const expected = bareReason instanceof Error ? bareReason : 'PDF reading cancelled.';
  check(expected === 'PDF reading cancelled.' ? error.message === expected : error === bareReason, `aborted without a reason -> ${error.message}`);
}
const hanging = await makePdf('hanging.pdf', 6);
process.env.SMOKE_HANG = '1';
const mid = new AbortController();
const midCall = readPdfPages({ file: hanging, vault, signal: mid.signal });
setTimeout(() => mid.abort(new Error('stopped mid-flight')), 50);
await rejects(midCall, 'stopped mid-flight', 'aborted while the worker runs');
delete process.env.SMOKE_HANG;

console.log(`\n${checks - failures.length}/${checks} checks passed`);
if (failures.length) { console.log(failures.map(failure => `- ${failure}`).join('\n')); process.exitCode = 1; }
await rm(root, { recursive: true, force: true });

