import { mkdtemp, mkdir, writeFile, readFile, stat, rm } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import { join, dirname } from 'node:path';
import { pathToFileURL } from 'node:url';

const failures = [];
let checks = 0;
const check = (condition, label) => { checks++; if (!condition) failures.push(label); console.log(`${condition ? 'ok  ' : 'FAIL'} ${label}`); };

function buildPdf(pageTexts) {
  const chunks = [];
  const offsets = [];
  let offset = 0;
  const push = text => { const buf = Buffer.from(text, 'latin1'); chunks.push(buf); offset += buf.length; };
  const add = (number, body) => { offsets[number] = offset; push(`${number} 0 obj\n${body}\nendobj\n`); };
  push('%PDF-1.7\n');
  const kids = pageTexts.map((_, index) => `${4 + index * 2} 0 R`).join(' ');
  add(1, '<< /Type /Catalog /Pages 2 0 R >>');
  add(2, `<< /Type /Pages /Kids [${kids}] /Count ${pageTexts.length} >>`);
  add(3, '<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica >>');
  pageTexts.forEach((text, index) => {
    const page = 4 + index * 2;
    add(page, `<< /Type /Page /Parent 2 0 R /MediaBox [0 0 612 792] /Resources << /Font << /F1 3 0 R >> >> /Contents ${page + 1} 0 R >>`);
    const stream = `BT /F1 24 Tf 72 700 Td (${text}) Tj ET`;
    add(page + 1, `<< /Length ${stream.length} >>\nstream\n${stream}\nendstream`);
  });
  const startxref = offset;
  push(`xref\n0 ${offsets.length}\n0000000000 65535 f \n`);
  for (let number = 1; number < offsets.length; number++) push(`${String(offsets[number]).padStart(10, '0')} 00000 n \n`);
  push(`trailer\n<< /Size ${offsets.length} /Root 1 0 R >>\nstartxref\n${startxref}\n%%EOF\n`);
  return Buffer.concat(chunks);
}

