  try {
    const meta = JSON.parse(await vault.readFile(`${directory}/meta.json`));
    const valid = meta?.version === CACHE_VERSION && meta.sha256 === digest && Number.isInteger(meta.totalPages) && meta.totalPages >= 1;
    if (valid) return meta;
  } catch {
    // The cache is derived data; an unreadable or stale meta.json just means extract again.
  }
  return null;
