import { open } from 'node:fs/promises';
import { createHash } from 'node:crypto';
import { Worker } from 'node:worker_threads';

const CACHE_VERSION = 'pdfium-2.1.13-v1';
const DEFAULT_PAGES = 20;
const MAX_PDF_BYTES = 50 * 1024 * 1024;
const MAX_PAGE_CHARS = 24000;
const MAX_IMAGES = 2;
const MAX_IMAGE_BYTES = 8 * 1024 * 1024;
const WORKER_TIMEOUT_MS = 60000;
const PDF_MARKER = Buffer.from('%PDF-');

const sha256 = data => createHash('sha256').update(data).digest('hex');
const stopError = signal => signal?.reason instanceof Error ? signal.reason : new Error('PDF reading cancelled.');
const pagePath = (directory, number, extension) => `${directory}/page-${String(number).padStart(4, '0')}.${extension}`;

async function readBytes(file) {
  let handle;
  try {
    handle = await open(file, 'r');
  } catch (error) {
    if (error?.code === 'ENOENT' || error?.code === 'EISDIR') throw new Error(`${file}: file not found.`);
    throw error;
  }
  try {
    const info = await handle.stat();
    if (!info.isFile()) throw new Error(`${file}: file not found.`);
    if (info.size > MAX_PDF_BYTES) throw new Error('The PDF is larger than 50 MiB.');
    const bytes = Buffer.alloc(info.size);
    let filled = 0;
    while (filled < bytes.length) {
      const { bytesRead } = await handle.read(bytes, filled, bytes.length - filled, filled);
      if (!bytesRead) break;
      filled += bytesRead;
    }
    return bytes.subarray(0, filled);
  } finally {
    await handle.close();
  }
}

async function readMeta(vault, directory, digest) {
  try {
    const meta = JSON.parse(await vault.readFile(`${directory}/meta.json`));
    const valid = meta?.version === CACHE_VERSION && meta.sha256 === digest && Number.isInteger(meta.totalPages) && meta.totalPages >= 1;
    if (valid) return meta;
  } catch {
    // The cache is derived data; an unreadable or stale meta.json just means extract again.
  }
  return null;
}

async function readCachedPage(vault, directory, number) {
  try {
    const path = pagePath(directory, number, 'txt');
    if (!(await vault.exists(path))) return null;
    const text = await vault.readFile(path);
    return typeof text === 'string' ? text : null;
  } catch {
    return null;
  }
}

// The worker rejects page numbers outside the document, so callers pass in-range pages only.
async function runWorker(bytes, pages, includeImages, signal) {
  if (signal?.aborted) throw stopError(signal);
  const worker = new Worker(new URL('./pdf-worker.mjs', import.meta.url), {
    workerData: { bytes: Uint8Array.from(bytes), pages, includeImages },
    execArgv: [], stdout: true, stderr: true,
    resourceLimits: { maxOldGenerationSizeMb: 128, maxYoungGenerationSizeMb: 32 },
  });
  worker.stdout.resume();
  worker.stderr.resume();
  try {
    const result = await new Promise((resolve, reject) => {
      const abort = () => reject(stopError(signal));
      const timer = setTimeout(() => reject(new Error('Reading the PDF timed out.')), WORKER_TIMEOUT_MS);
      const done = () => { clearTimeout(timer); signal?.removeEventListener('abort', abort); };
      worker.once('message', message => { done(); message.error ? reject(new Error(message.error)) : resolve(message); });
      worker.once('error', error => { done(); reject(error); });
      worker.once('exit', code => { done(); reject(new Error(`PDF worker exited before returning a result (${code}).`)); });
      signal?.addEventListener('abort', abort, { once: true });
      if (signal?.aborted) abort();
    });
    if (signal?.aborted) throw stopError(signal);
    return result;
  } finally {
    await worker.terminate();
  }
}

export async function readPdfPages({ file, vault, pages, includeImages = false, signal }) {
  if (signal?.aborted) throw stopError(signal);
  const defaulted = !Array.isArray(pages);
  const requested = defaulted
    ? Array.from({ length: DEFAULT_PAGES }, (_, index) => index + 1)
    : [...new Set(pages.filter(number => Number.isInteger(number) && number >= 1))].sort((left, right) => left - right);
  const bytes = await readBytes(file);
  if (!bytes.subarray(0, 1024).includes(PDF_MARKER)) throw new Error('That file is not a PDF.');
  const digest = sha256(bytes);
  const sha48 = digest.slice(0, 48);
  const directory = `_discover/pdf/${sha48}`;
  const meta = await readMeta(vault, directory, digest);
  let totalPages = meta ? meta.totalPages : 0;

  // Page renders exist only in the worker response and vault reads return text, so an image
  // request cannot be served from the text cache and re-extracts the pages whose render is kept.
  const texts = new Map();
  const renders = new Map();
  let extracted = false;
  const absorb = async result => {
    extracted = true;
    for (const page of result.pages) {
      if (signal?.aborted) throw stopError(signal);
      texts.set(page.number, { text: page.text, truncated: page.truncated === true });
      if (page.image) renders.set(page.number, page.image);
      await vault.writeFile(pagePath(directory, page.number, 'txt'), page.text);
    }
  };

  if (!totalPages) {
    // The page count is learned from a one-page probe before the remaining pages are requested,
    // because the worker rejects any page number beyond the end of the document. The probe carries
    // a render when its page is one of the pages whose render will be kept.
    const probeImages = includeImages && requested[0] === 1;
    const probe = await runWorker(bytes, [1], probeImages, signal);
    totalPages = probe.totalPages;
    await absorb(probe);
  }

  // Renders are kept for at most two pages, so only those pages are extracted with images; the rest
  // of the document is extracted as text. Rendering every page of a long PDF would be wasted work.
  const wanted = requested.filter(number => number <= totalPages);
  const renderWanted = new Set(includeImages ? wanted.slice(0, MAX_IMAGES) : []);
  const missingText = [];
  const missingRenders = [];
  for (const number of wanted) {
    if (renderWanted.has(number)) {
      if (!renders.has(number)) missingRenders.push(number);
    } else if (!texts.has(number)) {
      const text = await readCachedPage(vault, directory, number);
      if (text === null) missingText.push(number);
      else texts.set(number, { text, truncated: text.length >= MAX_PAGE_CHARS });
    }
  }
  if (missingRenders.length) await absorb(await runWorker(bytes, missingRenders, true, signal));
  if (missingText.length) await absorb(await runWorker(bytes, missingText, false, signal));

  if (extracted) {
    const cache = { version: CACHE_VERSION, sha256: digest, totalPages, extractedAt: new Date().toISOString() };
    await vault.writeFile(`${directory}/meta.json`, JSON.stringify(cache));
  }

  const output = [];
  const images = [];
  for (const number of requested) {
    if (number > totalPages) continue;
    const page = texts.get(number);
    if (!page) continue;
    const record = { number, text: page.text, truncated: page.truncated };
    const render = includeImages ? renders.get(number) : null;
    if (render && images.length < MAX_IMAGES && render.data.length <= MAX_IMAGE_BYTES) {
      const imagePath = pagePath(directory, number, 'png');
      await vault.writeFile(imagePath, Buffer.from(render.data));
      record.imagePath = imagePath;
      images.push({ number, data: Buffer.from(render.data).toString('base64'), mimeType: 'image/png' });
    }
    output.push(record);
  }
  const truncatedPages = defaulted && totalPages > DEFAULT_PAGES ? totalPages - DEFAULT_PAGES : 0;
  return { sha256: digest, sha48, totalPages, truncatedPages, pages: output, images };
}

